    const previous = this.entries.get(key);
    const version = (previous?.version ?? this.initialVersion - 1) + 1;
    this.entries.set(key, { value, version });
    return version;
  }

  versionOf(key: string): number | undefined {
    return this.entries.get(key)?.version;
  }
}

